(function auditTIUPaket3(){
  const bank = window.TIU_PAKET3;
  if (!Array.isArray(bank) || bank.length !== 35) {
    console.error("[TIU Paket 3] Bank tidak valid. Jumlah harus 35.");
    return;
  }
  const ids = new Set(bank.map(q => q?.id));
  const valid = bank.every(q =>
    q?.id && q?.question && Array.isArray(q.options) && q.options.length === 5 &&
    /^[A-E]$/.test(q.correct) &&
    q.options.every(o => /^[A-E]$/.test(o.k) && typeof o.t === "string")
  ) && ids.size === 35;
  if (!valid) {
    console.error("[TIU Paket 3] Audit struktur gagal.");
    return;
  }
  console.log("[TIU Paket 3] 35 soal berhasil dimuat.");
  console.log("[TIU Paket 3] Audit struktur: OK (27 non-figural + 8 figural, 5 opsi/soal, kunci lengkap).");
})();
